-- Refill the precomputed summary tables (schema/006_summaries.sql and
-- schema/008_read_cost.sql) from the current base data. Idempotent: clears
-- then repopulates, so it is safe to run after every data load and to re-run
-- against D1. Requires migrations 006 AND 008.
--
-- Used by:
--   * api/scripts/build.py — after merging source data, before dumping.
--   * production D1, once after applying 006-008 and again after any reload:
--       wrangler d1 execute rootfast --remote --file api/scripts/populate_summaries.sql
--
-- After running it against D1, bump DATASET_VERSION (or CACHE_EPOCH in
-- src/index.ts) and redeploy the Worker: the last statement here clears the
-- response store, but answers cached at Cloudflare's edge are keyed by that
-- version and otherwise live for up to a day.
--
-- Cost on D1: about 2.9 million rows written (5.5 million on a re-run, which
-- deletes first) and well over 10 million read. That fits the Workers Paid
-- allowance; it does NOT fit Workers Free (100,000 rows written per day).

DELETE FROM plant_endemic_state;
INSERT INTO plant_endemic_state (plant_id, state_code)
SELECT p.id, MIN(c.state_code)
  FROM plants p
  JOIN plant_county_distribution pcd ON pcd.plant_id  = p.id
  JOIN counties                  c   ON c.county_fips = pcd.county_fips
 WHERE p.is_synonym = 0 AND p.is_excluded = 0
 GROUP BY p.id
HAVING COUNT(DISTINCT c.state_code) = 1;

DELETE FROM county_taxa_summary;
INSERT INTO county_taxa_summary (county_fips, taxa_count, photo_count)
SELECT c.county_fips,
       COUNT(DISTINCT pcd.plant_id),
       COUNT(DISTINCT CASE WHEN p.photo_url IS NOT NULL THEN p.id END)
  FROM counties c
  LEFT JOIN plant_county_distribution pcd ON pcd.county_fips = c.county_fips
  LEFT JOIN plants                    p   ON p.id            = pcd.plant_id
 GROUP BY c.county_fips;

-- ---------------------------------------------------------------------
-- Migration 008 — read-cost summaries. Same contract as above: clear, then
-- refill from the base tables.
-- ---------------------------------------------------------------------

UPDATE county_taxa_summary
   SET accepted_count = 0, native_count = 0, introduced_count = 0, both_count = 0;
UPDATE county_taxa_summary
   SET (accepted_count, native_count, introduced_count, both_count) = (
         SELECT COUNT(*),
                COALESCE(SUM(pcd.nativity = 'Native'), 0),
                COALESCE(SUM(pcd.nativity = 'Introduced'), 0),
                COALESCE(SUM(pcd.nativity = 'Both'), 0)
           FROM plant_county_distribution pcd
           JOIN plants p ON p.id = pcd.plant_id
          WHERE pcd.county_fips = county_taxa_summary.county_fips
            AND p.is_synonym = 0 AND p.is_excluded = 0
       );

DELETE FROM plant_name_rank;
INSERT INTO plant_name_rank (plant_id, name_rank)
SELECT id, ROW_NUMBER() OVER (ORDER BY scientific_name, id)
  FROM plants
 WHERE is_synonym = 0 AND is_excluded = 0;

-- county_plants (one row per accepted distribution record, ~2.5M) and
-- state_plants are filled ONE STATE AT A TIME. D1 advises against a single
-- statement that modifies hundreds of thousands of rows; the largest slice
-- here is Texas at ~122,000. The first two characters of a county FIPS are
-- its state's FIPS, so the slices below ('01' .. '78', plus open-ended
-- slices at both ends) are exhaustive and never overlap, and each one maps
-- to exactly one state. county_plants joins plant_name_rank, which holds
-- accepted taxa only, so synonyms and excluded taxa never enter it.
-- (Generated: one DELETE + INSERT per slice.)
DELETE FROM county_plants WHERE county_fips < '01';
INSERT INTO county_plants (county_fips, name_rank, plant_id, nativity) SELECT pcd.county_fips, r.name_rank, pcd.plant_id, pcd.nativity FROM plant_county_distribution pcd JOIN plant_name_rank r ON r.plant_id = pcd.plant_id WHERE pcd.county_fips < '01';
DELETE FROM county_plants WHERE county_fips >= '01' AND county_fips < '02';
INSERT INTO county_plants (county_fips, name_rank, plant_id, nativity) SELECT pcd.county_fips, r.name_rank, pcd.plant_id, pcd.nativity FROM plant_county_distribution pcd JOIN plant_name_rank r ON r.plant_id = pcd.plant_id WHERE pcd.county_fips >= '01' AND pcd.county_fips < '02';
