DELETE FROM state_plants;
INSERT INTO state_plants (state_code, scientific_name, plant_id, county_count, native_counties, introduced_counties, both_counties) SELECT c.state_code, p.scientific_name, p.id, COUNT(*), SUM(pcd.nativity = 'Native'), SUM(pcd.nativity = 'Introduced'), SUM(pcd.nativity = 'Both') FROM plant_county_distribution pcd JOIN counties c ON c.county_fips = pcd.county_fips JOIN plants p ON p.id = pcd.plant_id WHERE p.is_synonym = 0 AND p.is_excluded = 0 AND pcd.county_fips < '01' GROUP BY c.state_code, p.id;
