DELETE FROM state_taxa_summary;
INSERT INTO state_taxa_summary (state_code, county_count, taxa_count)
SELECT c.state_code, COUNT(DISTINCT c.county_fips), COUNT(DISTINCT pcd.plant_id)
  FROM plant_county_distribution pcd
  JOIN counties c ON c.county_fips = pcd.county_fips
 GROUP BY c.state_code;
UPDATE state_taxa_summary
   SET county_count = (SELECT COUNT(*) FROM counties c WHERE c.state_code = state_taxa_summary.state_code),
       (accepted_count, native_count, introduced_count, both_count) = (
         SELECT COUNT(*),
                COALESCE(SUM(sp.native_counties > 0), 0),
                COALESCE(SUM(sp.introduced_counties > 0), 0),
                COALESCE(SUM(sp.both_counties > 0), 0)
           FROM state_plants sp
          WHERE sp.state_code = state_taxa_summary.state_code
       );

DELETE FROM plant_range_summary;
INSERT INTO plant_range_summary (plant_id, county_count)
SELECT plant_id, COUNT(*)
  FROM plant_county_distribution
 GROUP BY plant_id;

